#!/usr/bin/env node
// spec/*.json (+ spec/i18n/*.en.json) → typed wrappers for every SDK + reference docs.
//
//   node tools/codegen.mjs           # write generated files
//   node tools/codegen.mjs --check   # exit 1 if any generated file is stale (CI)
//
// One spec drives every language, so the TypeScript, Python and Go clients can never
// disagree about tool names, action names or required scopes.

import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { spawnSync } from "node:child_process";

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const CHECK = process.argv.includes("--check");
const SERVERS = ["studio", "team", "open"];
const readJson = (p, d) => (fs.existsSync(p) ? JSON.parse(fs.readFileSync(p, "utf8")) : d);

// Actions the SDK deliberately does NOT wrap. They stay callable through the raw
// `call()` API and are listed in the reference, but no convenience method exists.
//   studio_confirm.decide — records the human's click on an approval card. It belongs to
//   the card UI; code that calls it would be approving its own spending.
const NO_WRAPPER = new Set(["studio_confirm.decide"]);

const camel = (s) => s.replace(/_([a-z0-9])/g, (_, c) => c.toUpperCase());
const pascal = (s) => { const c = camel(s); return c[0].toUpperCase() + c.slice(1); };
const PY_KW = new Set(("False None True and as assert async await break class continue def del elif else except finally "
  + "for from global if import in is lambda nonlocal not or pass raise return try while with yield match case").split(" "));
const pyName = (s) => (PY_KW.has(s) ? s + "_" : s);
const groupOf = (server, tool) => (tool === server ? "core" : tool.startsWith(server + "_") ? tool.slice(server.length + 1) : tool);
const oneLine = (s) => String(s || "").replace(/\s+/g, " ").trim();

function load(server) {
  const spec = readJson(path.join(ROOT, "spec", `${server}.json`));
  const en = readJson(path.join(ROOT, "spec", "i18n", `${server}.en.json`), { tools: {}, actions: {}, params: {} });
  const groups = spec.tools.map((t) => {
    const actions = (t["x-actions"] || []).map((a) => ({
      ...a,
      key: `${t.name}.${a.name}`,
      en: oneLine(en.actions?.[`${t.name}.${a.name}`] || a.summary),
      paramsEn: Object.keys(a.params || {}).map((p) => [p, oneLine(en.params?.[`${t.name}.${a.name}.${p}`] || a.params[p])]),
      wrapped: !NO_WRAPPER.has(`${t.name}.${a.name}`),
    }));
    return {
      tool: t.name, group: groupOf(server, t.name), title: t.title || t.annotations?.title || t.name,
      overview: oneLine(en.tools?.[t.name] || t.description?.split("\n")[0] || ""),
      annotations: t.annotations || {}, actions, schema: t.inputSchema,
    };
  });
  return { server, spec, groups };
}

const scopesOf = (a) => a.scopes || [];
// Studio: destructiveConfirm = send `confirm: true` after asking. Team: a non-null `confirm`
// (spend / apply / destroy / dynamic) = the server answers needs_confirmation with a token.
const flags = (a) => [a.spends ? "paid" : "", a.destructiveConfirm ? "confirm" : "",
  a.confirm ? (a.confirm === "dynamic" ? "approval (some args)" : "approval") : "",
  a.usesPlatformLlm ? "llm" : "", a.returnsImage ? "image" : ""].filter(Boolean);
const docLine = (a) => {
  const f = flags(a);
  return `${a.en}${a.en.endsWith(".") ? "" : "."} Scopes: ${scopesOf(a).join(" + ") || "none"}${f.length ? ". Flags: " + f.join(", ") : ""}.`;
};

// ── TypeScript ──────────────────────────────────────────────────────────────
function genTs({ server, spec, groups }) {
  const P = pascal(server);
  const esc = (s) => s.replace(/\*\//g, "* /");
  let o = `// GENERATED by tools/codegen.mjs from spec/${server}.json — do not edit by hand.\n`
    + `import { McpClient, type ClientOptions, type CallOptions, type Params, type ToolResult } from "../client.js";\n\n`;
  const scopeMap = {};
  for (const g of groups) for (const a of g.actions) scopeMap[a.key] = scopesOf(a);
  o += `/** Scopes each action needs, keyed "tool.action". Used for client-side preflight. */\n`
    + `export const ${server.toUpperCase()}_ACTION_SCOPES: Readonly<Record<string, readonly string[]>> = ${JSON.stringify(scopeMap)};\n\n`;
  const flat = groups.filter((g) => !g.actions.length), grouped = groups.filter((g) => g.actions.length);
  for (const g of grouped) {
    const cls = `${P}${pascal(g.group)}`;
    o += `/** \`${g.tool}\` — ${esc(g.title)}. ${esc(g.overview)} */\nexport class ${cls} {\n  constructor(private readonly c: McpClient) {}\n`;
    for (const a of g.actions) {
      if (!a.wrapped) continue;
      o += `  /** ${esc(docLine(a))} */\n  ${camel(a.name)}(params: Params = {}, opts?: CallOptions): Promise<ToolResult> {\n`
        + `    return this.c.call(${JSON.stringify(g.tool)}, { ...params, action: ${JSON.stringify(a.name)} }, opts);\n  }\n`;
    }
    o += `}\n\n`;
  }
  o += `/** Typed client for the ${server} MCP server (${spec.endpoint}). */\nexport class ${P}Client extends McpClient {\n`;
  for (const g of grouped) o += `  readonly ${camel(g.group)}: ${P}${pascal(g.group)};\n`;
  o += `  constructor(opts: Omit<ClientOptions, "server" | "actionScopes" | "endpoint"> & { endpoint?: string }) {\n`
    + `    super({ ...opts, server: ${JSON.stringify(server)}, endpoint: opts.endpoint ?? ${JSON.stringify(spec.endpoint)}, actionScopes: ${server.toUpperCase()}_ACTION_SCOPES });\n`;
  for (const g of grouped) o += `    this.${camel(g.group)} = new ${P}${pascal(g.group)}(this);\n`;
  o += `  }\n`;
  for (const g of flat) o += `  /** \`${g.tool}\` — ${esc(oneLine(g.overview || g.title))} */\n  ${camel(g.tool)}(args: Params = {}, opts?: CallOptions): Promise<ToolResult> {\n    return this.call(${JSON.stringify(g.tool)}, args, opts);\n  }\n`;
  o += `}\n`;
  return o;
}

// ── Python ──────────────────────────────────────────────────────────────────
function genPy({ server, spec, groups }) {
  const P = pascal(server);
  const esc = (s) => s.replace(/\\/g, "\\\\").replace(/"""/g, '\\"\\"\\"');
  const scopeMap = {};
  for (const g of groups) for (const a of g.actions) scopeMap[a.key] = scopesOf(a);
  let o = `# GENERATED by tools/codegen.mjs from spec/${server}.json — do not edit by hand.\n`
    + `from typing import Any, Dict, Optional\n\nfrom ..client import McpClient, ToolResult\n\n`
    + `${server.toUpperCase()}_ACTION_SCOPES: Dict[str, tuple] = {\n`
    + Object.entries(scopeMap).map(([k, v]) => `    ${JSON.stringify(k)}: (${v.map((x) => JSON.stringify(x)).join(", ")}${v.length === 1 ? "," : ""}),`).join("\n")
    + `\n}\n\n`;
  const flat = groups.filter((g) => !g.actions.length), grouped = groups.filter((g) => g.actions.length);
  for (const g of grouped) {
    const cls = `${P}${pascal(g.group)}`;
    o += `class ${cls}:\n    """\`${g.tool}\` — ${esc(g.title)}. ${esc(g.overview)}"""\n\n    def __init__(self, client: McpClient) -> None:\n        self._c = client\n\n`;
    for (const a of g.actions) {
      if (!a.wrapped) continue;
      o += `    def ${pyName(a.name)}(self, params: Optional[Dict[str, Any]] = None, /, **kw: Any) -> ToolResult:\n`
        + `        """${esc(docLine(a))}"""\n`
        + `        return self._c.call(${JSON.stringify(g.tool)}, {**(params or {}), **kw, "action": ${JSON.stringify(a.name)}})\n\n`;
    }
  }
  o += `class ${P}Client(McpClient):\n    """Typed client for the ${server} MCP server (${spec.endpoint})."""\n\n`
    + `    def __init__(self, api_key: Optional[str] = None, *, endpoint: str = ${JSON.stringify(spec.endpoint)}, **kw: Any) -> None:\n`
    + `        super().__init__(server=${JSON.stringify(server)}, endpoint=endpoint, api_key=api_key, action_scopes=${server.toUpperCase()}_ACTION_SCOPES, **kw)\n`;
  for (const g of grouped) o += `        self.${pyName(g.group)} = ${P}${pascal(g.group)}(self)\n`;
  for (const g of flat) o += `\n    def ${pyName(g.tool)}(self, params: Optional[Dict[str, Any]] = None, /, **kw: Any) -> ToolResult:\n`
    + `        """\`${g.tool}\` — ${esc(oneLine(g.overview || g.title))}"""\n        return self.call(${JSON.stringify(g.tool)}, {**(params or {}), **kw})\n`;
  return o;
}

// ── Go ──────────────────────────────────────────────────────────────────────
function genGo({ server, spec, groups }) {
  const P = pascal(server);
  const cm = (s) => s.replace(/\n/g, " ");
  let o = `// Code generated by tools/codegen.mjs from spec/${server}.json. DO NOT EDIT.\n\npackage algohash\n\nimport "context"\n\n`;
  o += `// ${P}ActionScopes lists the scopes each action needs, keyed "tool.action".\nvar ${P}ActionScopes = map[string][]string{\n`;
  for (const g of groups) for (const a of g.actions) o += `\t${JSON.stringify(a.key)}: {${scopesOf(a).map((x) => JSON.stringify(x)).join(", ")}},\n`;
  o += `}\n\n`;
  const flat = groups.filter((g) => !g.actions.length), grouped = groups.filter((g) => g.actions.length);
  for (const g of grouped) {
    const t = `${P}${pascal(g.group)}`;
    o += `// ${t} wraps the ${g.tool} tool — ${cm(g.title)}. ${cm(g.overview)}\ntype ${t} struct{ c *Client }\n\n`;
    for (const a of g.actions) {
      if (!a.wrapped) continue;
      o += `// ${pascal(a.name)}: ${cm(docLine(a))}\nfunc (g ${t}) ${pascal(a.name)}(ctx context.Context, p Params) (*ToolResult, error) {\n`
        + `\treturn g.c.CallAction(ctx, ${JSON.stringify(g.tool)}, ${JSON.stringify(a.name)}, p)\n}\n\n`;
    }
  }
  o += `// ${P}Client is a typed client for the ${server} MCP server (${spec.endpoint}).\ntype ${P}Client struct {\n\t*Client\n`;
  for (const g of grouped) o += `\t${pascal(g.group)} ${P}${pascal(g.group)}\n`;
  o += `}\n\n// New${P} creates a ${server} client. The API key is sent as a Bearer token.\nfunc New${P}(apiKey string, opts ...Option) *${P}Client {\n`
    + `\tc := newClient(${JSON.stringify(server)}, ${JSON.stringify(spec.endpoint)}, apiKey, ${P}ActionScopes, opts...)\n\treturn &${P}Client{Client: c,\n`;
  for (const g of grouped) o += `\t\t${pascal(g.group)}: ${P}${pascal(g.group)}{c},\n`;
  o += `\t}\n}\n`;
  for (const g of flat) o += `\n// ${pascal(g.tool)} calls ${g.tool} — ${cm(oneLine(g.overview || g.title))}\nfunc (c *${P}Client) ${pascal(g.tool)}(ctx context.Context, p Params) (*ToolResult, error) {\n\treturn c.Call(ctx, ${JSON.stringify(g.tool)}, p)\n}\n`;
  return o;
}

// ── Reference docs ──────────────────────────────────────────────────────────
const cell = (s) => String(s).replace(/\|/g, "\\|");
function genRef({ server, spec, groups }) {
  const P = pascal(server);
  let o = `<!-- GENERATED by tools/codegen.mjs from spec/${server}.json — do not edit by hand. -->\n# ${P} MCP — tool reference\n\n`
    + `Endpoint: \`${spec.endpoint}\` · server version ${spec.serverVersion} · `
    + `${groups.length} tools · ${groups.reduce((n, g) => n + g.actions.length, 0)} actions\n\n`
    + `Legend: **paid** = spends HWT (needs \`spend\` scope; quotes above the confirm threshold come back as \`needs_confirmation\`) · `
    + `**confirm** = destructive, send \`confirm: true\` only after the user agreed · **approval** = the server answers \`needs_confirmation\` with a single-use token · `
    + `**llm** = runs on the platform text model (metered) · **image** = result includes an image content block.\n\n`
    + `SDK accessors: TypeScript \`client.<group>.<action>()\` (camelCase) · Python \`client.<group>.<action>()\` (snake_case) · Go \`client.<Group>.<Action>(ctx, p)\`.\n\n`;
  o += `| Tool | Group | Actions | Read-only |\n|---|---|---|---|\n`;
  for (const g of groups) o += `| [\`${g.tool}\`](#${g.tool}) | \`${g.group}\` | ${g.actions.length || "—"} | ${g.annotations.readOnlyHint ? "yes" : "no"} |\n`;
  for (const g of groups) {
    o += `\n## ${g.tool}\n\n**${cell(g.title)}.** ${g.overview}\n\n`;
    if (g.actions.length) {
      o += `| Action | Scopes | Flags | What it does |\n|---|---|---|---|\n`;
      for (const a of g.actions) o += `| \`${a.name}\`${a.wrapped ? "" : " ⁽¹⁾"} | ${scopesOf(a).map((s) => `\`${s}\``).join(" + ")} | ${flags(a).join(", ")} | ${cell(a.en)} |\n`;
      const withArgs = g.actions.filter((a) => a.paramsEn && a.paramsEn.length);
      if (withArgs.length) {
        o += `\n<details><summary>Arguments</summary>\n\n`;
        for (const a of withArgs) o += `- **\`${a.name}\`** — ${a.paramsEn.map(([p, d]) => `\`${p}\`: ${d}`).join("; ")}\n`;
        o += `\n</details>\n`;
      }
      if (g.actions.some((a) => !a.wrapped)) o += `\n⁽¹⁾ No SDK wrapper on purpose: this action is pressed by the approval card UI, not by your code. See [approvals](../approvals.md).\n`;
    } else {
      const props = Object.entries(g.schema?.properties || {});
      o += props.length ? `| Argument | Type | Description |\n|---|---|---|\n` + props.map(([k, v]) => `| \`${k}\`${(g.schema.required || []).includes(k) ? " *(required)*" : ""} | ${v.type || "any"} | ${cell(oneLine(v.description || ""))} |`).join("\n") + "\n" : "No arguments.\n";
    }
  }
  return o;
}

function genPermissions(all) {
  let o = `<!-- GENERATED by tools/codegen.mjs — do not edit by hand. -->\n# Permission matrix\n\n`
    + `Every action needs **all** of the scopes listed for it. Scopes are independent: \`spend\` does not imply \`edit\`.\n\n`;
  for (const { server, spec, groups } of all) {
    const acts = groups.flatMap((g) => g.actions);
    if (!acts.length) { o += `## ${server}\n\nNo scopes. Every tool works with any valid key; spending is limited by the key's monthly cap.\n\n`; continue; }
    o += `## ${server}\n\nScopes: ${spec.scopes.map((s) => `\`${s}\``).join(", ")} · new keys default to ${spec.defaultNewKeyScopes.map((s) => `\`${s}\``).join(" + ")}\n\n`;
    const combos = new Map();
    for (const a of acts) { const k = scopesOf(a).join(" + "); combos.set(k, (combos.get(k) || 0) + 1); }
    o += `| Needs | Actions |\n|---|---|\n` + [...combos].sort((a, b) => b[1] - a[1]).map(([k, n]) => `| \`${k}\` | ${n} |`).join("\n") + "\n\n";
    o += `What a key can do, by scope set:\n\n| Key scopes | Allowed | Denied |\n|---|---|---|\n`;
    const presets = server === "studio"
      ? [["read"], ["read", "edit"], ["read", "edit", "spend"], ["read", "edit", "spend", "publish"]]
      : [["read"], ["read", "edit"], ["read", "edit", "spend"]];
    for (const p of presets) {
      const allowed = acts.filter((a) => scopesOf(a).every((s) => p.includes(s))).length;
      o += `| ${p.map((s) => `\`${s}\``).join(" + ")} | ${allowed} | ${acts.length - allowed} |\n`;
    }
    o += `\n`;
    if (server === "team") {
      o += `Some Team actions need **more** scopes depending on their arguments (the table above shows the base scope). `
        + `The server re-checks on every call:\n\n`
        + `- \`team.create_agent\`, \`team.set_tools\`, \`team.set_caps\`, \`team.set_type\` → \`edit + spend\` when they grant a high-risk or unrestricted tool.\n`
        + `- \`team.set_budget\` → \`edit + spend\` when it removes the cap.\n`
        + `- \`team.set_persona\` → \`edit + spend\` when it turns a schedule on.\n`
        + `- \`team_blueprint.install_template\` → \`edit + spend\` for community templates.\n`
        + `- \`team_evolve.settings\` → \`edit + spend\` when it turns automatic evolution on.\n\n`;
    }
    if (server === "studio") {
      o += `Some Studio actions also change scope with their arguments: \`analyze_refs\` with \`mode: "style"\` is \`spend\`; `
        + `blog generation that is not a draft is \`spend + publish\`; \`motion_create\` (with a \`prompt\`) and \`motion_direct_reply\` `
        + `are \`edit\` when no platform text model runs and are refused without \`spend\` when one does. The server is always the authority.\n\n`;
    }
  }
  return o;
}

// Go output goes through gofmt so `--check` matches what `gofmt -l` expects. gofmt is required.
function gofmt(src) {
  const r = spawnSync("gofmt", [], { input: src, encoding: "utf8" });
  if (r.error || r.status !== 0) { console.error("gofmt is required for Go codegen:", r.error?.message || r.stderr); process.exit(2); }
  return r.stdout;
}

// ── write / check ───────────────────────────────────────────────────────────
const all = SERVERS.map(load);
const files = new Map();
for (const s of all) {
  files.set(`sdks/typescript/src/generated/${s.server}.ts`, genTs(s));
  files.set(`sdks/python/algohash_mcp/_generated/${s.server}.py`, genPy(s));
  files.set(`sdks/go/algohash/gen_${s.server}.go`, gofmt(genGo(s)));
  files.set(`docs/reference/${s.server}.md`, genRef(s));
}
files.set(`sdks/python/algohash_mcp/_generated/__init__.py`, `# GENERATED by tools/codegen.mjs — do not edit by hand.\n`);
files.set(`docs/reference/permissions.md`, genPermissions(all));

let stale = 0;
for (const [rel, content] of files) {
  const p = path.join(ROOT, rel);
  const cur = fs.existsSync(p) ? fs.readFileSync(p, "utf8") : null;
  if (cur === content) continue;
  if (CHECK) { console.error(`stale: ${rel}`); stale++; continue; }
  fs.mkdirSync(path.dirname(p), { recursive: true });
  fs.writeFileSync(p, content);
  console.log(`wrote ${rel}`);
}
if (CHECK && stale) { console.error(`${stale} generated file(s) out of date — run: node tools/codegen.mjs`); process.exit(1); }
if (CHECK) console.log("generated files up to date");
